BITMAPS = zlib.decompress(base64.b85decode(_CJK_B85))
assert len(BITMAPS) == (LAST_CODEPOINT - FIRST_CODEPOINT + 1) * BYTES_PER_GLYPH


def glyph_rows(character: str) -> tuple[int, ...] | None:
    codepoint = ord(character)
    if not FIRST_CODEPOINT <= codepoint <= LAST_CODEPOINT:
        return None
    offset = (codepoint - FIRST_CODEPOINT) * BYTES_PER_GLYPH
    glyph = BITMAPS[offset : offset + BYTES_PER_GLYPH]
    return tuple(int.from_bytes(glyph[index : index + 2], "big") for index in range(0, 32, 2))
